import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {RouterModule} from '@angular/router';import {Subscription} from 'rxjs';import {LegalService} from '../services/legal.service';import {LanguageService} from '../services/language.service';import {SiteTextPipe} from '../home/site-text.pipe';import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';
@Component({standalone:true,imports:[CommonModule,RouterModule,PlatformLayoutComponent,SiteTextPipe],template:`<app-platform-layout><main class="faq" [attr.lang]="content?.language"><p>GoDirect · All Digital Network</p><h1>{{content?.faq.title || ('ui.legal.faq' | siteText)}}</h1><p>{{content?.faq.intro}}</p><nav><a routerLink="/legal">{{'ui.legal.conditions' | siteText}}</a> · <a [href]="'mailto:'+content?.labels.contactEmail">{{'ui.legal.contact' | siteText}}</a></nav><p role="alert" *ngIf="error">{{'ui.legal.contact' | siteText}}</p><section *ngFor="let group of content?.faq.groups"><h2>{{group.title}}</h2><details *ngFor="let item of group.items"><summary>{{item.question}}</summary><p>{{item.answer}}</p></details></section><p>{{content?.faq.disclaimer}}</p></main></app-platform-layout>`,styles:[`.faq{max-width:950px;margin:auto;padding:40px 24px;color:#153c48}h1{font-size:2.5rem}section{margin:36px 0}details{padding:18px 0;border-bottom:1px solid #d3dfe1}summary{font-weight:600;cursor:pointer}p{line-height:1.65}a{color:#14546c}`]})export class FaqComponent implements OnInit,OnDestroy{content:any;error=false;private sub?:Subscription;private request=0;constructor(private api:LegalService,private language:LanguageService){}ngOnInit(){this.sub=this.language.language$.subscribe(()=>{void this.load();});}async load(){const n=++this.request;this.content=null;this.error=false;try{const content=await this.api.content();if(n===this.request)this.content=content;}catch{if(n===this.request)this.error=true;}}ngOnDestroy(){this.request++;this.sub?.unsubscribe();}}
